examples.template:
MonarchButton({{trigger}}) { isOpen = true }
    .popover(isPresented: $isOpen, arrowEdge: .top) {
        VStack(alignment: .leading, spacing: theme.spacing.space3) {
            HStack(alignment: .top) {
                Text("Keyboard shortcuts")
                    .monarchTextStyle(.heading)
                    .accessibilityAddTraits(.isHeader)
                    .frame(maxWidth: .infinity, alignment: .leading)
                Button { isOpen = false } label: {
                    Image(systemName: "xmark").frame(width: 24, height: 24)
                }
                .buttonStyle(.plain)
                .accessibilityLabel("Close")
            }
            Text({{description}})
                .monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
            MonarchTextField("Filter shortcuts", text: $query, prompt: "Filter shortcuts", labelVisibility: .hidden) {
                Image(systemName: "magnifyingglass")
            } trailing: {
                EmptyView()
            }
            ForEach(sections.indices, id: \.self) { index in
                VStack(alignment: .leading, spacing: theme.spacing.space2) {
                    if let group = sections[index].group {
                        Text(group)
                            .monarchTextStyle(.label)
                            .textCase(.uppercase)
                            .foregroundStyle(theme.colors.textMuted)
                            .accessibilityAddTraits(.isHeader)
                    }
                    ForEach(sections[index].items) { item in
                        if item.id != sections[index].items.first?.id { Divider() }
                        HStack(spacing: theme.spacing.space1) {
                            Text(item.label).monarchTextStyle(.body)
                            Spacer(minLength: theme.spacing.space2)
                            ForEach(item.keys.indices, id: \.self) { key in
                                if key > 0, !item.joiner.isEmpty {
                                    Text(item.joiner)
                                        .monarchTextStyle(.caption)
                                        .foregroundStyle(theme.colors.textMuted)
                                }
                                MonarchKbd(item.keys[key], isAlwaysVisible: true)
                            }
                        }
                    }
                }
            }
        }
        .foregroundStyle(theme.colors.textDefault)
        .padding(theme.spacing.space4)
        .frame(width: 340)
        .presentationCompactAdaptation(.popover)
        .presentationBackground(theme.colors.bgRaised)
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = false
@State private var query = ""

private struct Shortcut: Identifiable {
    let id: String
    let label: String
    let keys: [String]
    let joiner: String
}

private var sections: [(group: String?, items: [Shortcut])] {
    [
        (nil, [
            Shortcut(id: "search", label: {{sections.0.items.0.label}}, keys: ["⌘", "K"], joiner: ""),
            Shortcut(id: "help", label: {{sections.0.items.1.label}}, keys: ["?"], joiner: ""),
        ]),
        ({{sections.1.group}}, [
            Shortcut(id: "create", label: {{sections.1.items.0.label}}, keys: ["C"], joiner: ""),
            Shortcut(id: "next", label: {{sections.1.items.1.label}}, keys: ["J", "↓"], joiner: "or"),
            Shortcut(id: "previous", label: {{sections.1.items.2.label}}, keys: ["K", "↑"], joiner: "or"),
            Shortcut(id: "select", label: {{sections.1.items.3.label}}, keys: ["X"], joiner: ""),
            Shortcut(id: "open", label: {{sections.1.items.4.label}}, keys: ["↵"], joiner: ""),
        ]),
        ({{sections.2.group}}, [
            Shortcut(id: "inbox", label: {{sections.2.items.0.label}}, keys: ["G", "I"], joiner: "then"),
            Shortcut(id: "projects", label: {{sections.2.items.1.label}}, keys: ["G", "P"], joiner: "then"),
            Shortcut(id: "close", label: {{sections.2.items.2.label}}, keys: ["Esc"], joiner: ""),
        ]),
    ]
}

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = false
@State private var query = ""

private struct Shortcut: Identifiable {
    let id: String
    let label: String
    let keys: [String]
    let joiner: String
}

private var sections: [(group: String?, items: [Shortcut])] {
    [
        (nil, [
            Shortcut(id: "search", label: "Search and commands", keys: ["⌘", "K"], joiner: ""),
            Shortcut(id: "help", label: "Show this list", keys: ["?"], joiner: ""),
        ]),
        ("Tasks", [
            Shortcut(id: "create", label: "Create task", keys: ["C"], joiner: ""),
            Shortcut(id: "next", label: "Next task", keys: ["J", "↓"], joiner: "or"),
            Shortcut(id: "previous", label: "Previous task", keys: ["K", "↑"], joiner: "or"),
            Shortcut(id: "select", label: "Select the focused task", keys: ["X"], joiner: ""),
            Shortcut(id: "open", label: "Open the focused task", keys: ["↵"], joiner: ""),
        ]),
        ("Navigation", [
            Shortcut(id: "inbox", label: "Go to inbox", keys: ["G", "I"], joiner: "then"),
            Shortcut(id: "projects", label: "Go to projects", keys: ["G", "P"], joiner: "then"),
            Shortcut(id: "close", label: "Close panel or clear selection", keys: ["Esc"], joiner: ""),
        ]),
    ]
}

